def fetch_data(self):
    result = ''
    line = ''
    while True:
        c = self.serial.read()
        if c == chr(13):
            next # ignore CR
        line += c
        if c == chr(10):
            result += line
            line = ''
            next
        if line.endswith('ch>'):
            # stop on prompt
            break
    return result

def fetch_array(self, sel):
    def hex16(h):
        return struct.unpack('>h', h.decode('hex'))[0]
    self.send_command("data %d\r" % sel)
    data = self.fetch_data()
    x = []
    for line in data.split('\n'):
        if line:
            x.extend([hex16(d) for d in line.strip().split(' ')])
    return np.array(x)

def data(self, sel = 0):
    self.send_command("data %d\r" % sel)
    data = self.fetch_data()
    x = []
    for line in data.split('\n'):
        if line:
            d = line.strip().split(' ')
            x.append(float(d[0])+float(d[1])*1.j)
    return np.array(x)

